import{az as a,P as r,Q as i,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/vue/设计思想.md","filePath":"面试题/vue/设计思想.md","lastUpdated":1746243530000}'),o={name:"面试题/vue/设计思想.md"};function d(n,e,c,s,p,l){return r(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="mvc-和-mvvm-双向数据绑定-双向数据传递" tabindex="-1">MVC 和 MVVM （双向数据绑定）（双向数据传递） <a class="header-anchor" href="#mvc-和-mvvm-双向数据绑定-双向数据传递" aria-label="Permalink to “MVC 和 MVVM （双向数据绑定）（双向数据传递）”">​</a></h2><p>MVVM是Model-View-ViewModel的简写。它本质上就是MVC 的改进版。MVVM 就是将其中的View 的状态和行为抽象化，让我们将视图 UI 和业务逻辑分开。通过数据驱动（VM）视图（View）。当数据变化时，自动去刷新页面DOM，这使得我们能从繁琐的DOM操作中解放出来，从而专心地去处理业务逻辑。</p><h2 id="单向数据流" tabindex="-1">单向数据流 <a class="header-anchor" href="#单向数据流" aria-label="Permalink to “单向数据流”">​</a></h2><p>组件之间进行数据传递，无法直接将传递进来的数据进行修改，而是通过父组件提供的方法进行修改，达到显式行为，让状态修改有迹可寻。一个父组件有多个子组件，父组件单独可以修改数据时可以让数据流更清晰、更容易追踪，子组件逐渐庞大后，避免子组件意外修改父组件状态导致的难以调试的问题。所有状态变化都经过父组件处理，这样数据流动的方向单一，组件之间的关系更明确，维护起来也更容易</p><h2 id="为什么要使用虚拟-dom" tabindex="-1">为什么要使用虚拟 DOM <a class="header-anchor" href="#为什么要使用虚拟-dom" aria-label="Permalink to “为什么要使用虚拟 DOM”">​</a></h2><p>性能提升</p><h2 id="provide-inject-provide-consumer" tabindex="-1">provide inject， provide consumer <a class="header-anchor" href="#provide-inject-provide-consumer" aria-label="Permalink to “provide inject， provide consumer”">​</a></h2><p>解决了数据上下级组件穿透的问题，并没有解决平行组件的问题，如果需要数据传递到平行组件，则需要将数据传递到父组件然后再由平行组件使用，会造成逻辑臃肿和增加维护成本，浪费资源</p>',8)])])}const v=a(o,[["render",d]]);export{h as __pageData,v as default};
